242	    /**
243	     * Build the owner's customer code in the form '<LAST3>-<NNNN>' where LAST3 is the
244	     * upper-cased first three letters of the owner's last name and NNNN is a global
245	     * 4-digit zero-padded sequence equal to one more than the current number of owners.
246	     */
247	    private String generateCustomerCode(Owner owner) {
248	        String lastName = owner.getLastName();
